SET NOCOUNT ON;
DECLARE @Now datetimeoffset(7)=SYSUTCDATETIME();
MERGE dbo.Countries AS target USING (VALUES
(CAST('019c0000-0000-7000-8000-000000000001' AS uniqueidentifier),CAST('CO' AS char(2)),CAST(N'Colombia' AS nvarchar(120)),CAST(1 AS bit)),
(CAST('019c0000-0000-7000-8000-000000000002' AS uniqueidentifier),CAST('VE' AS char(2)),CAST(N'Venezuela' AS nvarchar(120)),CAST(1 AS bit))
) AS source(CountryId,Code,Name,IsActive) ON target.Code=source.Code
WHEN MATCHED THEN UPDATE SET Name=source.Name,IsActive=source.IsActive,UpdatedAt=@Now
WHEN NOT MATCHED THEN INSERT(CountryId,Code,Name,IsActive,CreatedAt) VALUES(source.CountryId,source.Code,source.Name,source.IsActive,@Now);

